import {
  AudioSource,
  AudioUtils,
  Entity,
  PlaybackMode,
  Vector3,
  World,
} from '@iwsdk/core';

/** Files are generated by scripts/make-sounds.mjs into public/audio/. */
const url = (file: string) => `${import.meta.env.BASE_URL}audio/${file}`;

export const SNAP_NOTES = 8;

/**
 * Game sound effects. Each effect is one entity with a positional
 * AudioSource; it is moved to where the event happens just before playing,
 * so pick, snap and wrong come from the piece itself.
 */
export class Sounds {
  private pickFx: Entity;
  private wrongFx: Entity;
  private snapFx: Entity[] = [];
  private winFx: Entity;
  private completeFx: Entity;
  private ambient: Entity;
  private musicPlaying = false;

  constructor(world: World) {
    const make = (
      file: string,
      volume: number,
      positional = true,
      loop = false,
    ): Entity => {
      const entity = world.createTransformEntity();
      entity.addComponent(AudioSource, {
        src: url(file),
        volume,
        positional,
        loop,
        refDistance: 0.6,
        playbackMode: PlaybackMode.Overlap,
        maxInstances: 3,
      });
      return entity;
    };
    this.pickFx = make('pick.wav', 0.5);
    this.wrongFx = make('wrong.wav', 0.55);
    for (let i = 0; i < SNAP_NOTES; i++) {
      this.snapFx.push(make(`snap-${i}.wav`, 0.75));
    }
    this.winFx = make('win.wav', 0.7, false);
    this.completeFx = make('complete.wav', 0.8, false);
    this.ambient = make('ambient.wav', 0.22, false, true);
  }

  private at(entity: Entity, position: Vector3): void {
    entity.object3D!.position.copy(position);
    AudioUtils.play(entity);
  }

  pick(position: Vector3): void {
    this.at(this.pickFx, position);
  }

  wrong(position: Vector3): void {
    this.at(this.wrongFx, position);
  }

  /** `step` is how many pieces are placed on this board so far (0-based). */
  snap(position: Vector3, step: number): void {
    const note = Math.min(SNAP_NOTES - 1, Math.max(0, step));
    this.at(this.snapFx[note], position);
  }

  win(): void {
    AudioUtils.play(this.winFx);
  }

  complete(): void {
    AudioUtils.play(this.completeFx);
  }

  setMusic(on: boolean): void {
    if (on === this.musicPlaying) return;
    this.musicPlaying = on;
    if (on) AudioUtils.play(this.ambient, 2);
    else AudioUtils.stop(this.ambient);
  }
}
